do $m$ declare s text; begin select pg_get_functiondef('facodi.kf_run_private_av_review_v1()'::regprocedure) into s; s:=replace(s,'recent where outcome in','recent where recent.outcome in'); if position('recent.outcome' in s)=0 then raise exception 'Unexpected definition'; end if; execute s; end $m$; revoke all on function facodi.kf_run_private_av_review_v1() from public,anon,authenticated,service_role;
